358	                // Audit-only event; no message produced.
359	                contributions.push(0);
360	            }
361	            SessionEvent::Compacted {
362	                summary,
363	                original_count,
364	                ..
365	            } => {
366	                let n = usize::try_from(*original_count).unwrap_or(usize::MAX);
367	                if n == 0 {
