        let tool = tools.iter().find(|t| t.name() == call.name).cloned();
        let effect = tool
            .as_ref()
            .map(|t| t.effect())
            .unwrap_or(crate::ToolEffect::SideEffect);
        let call_id = call.call_id.clone();

