171	                    out.push(event::tool_call_args(call_id, args_delta));
172	                } else if self.open_call.is_none() {
173	                    // Nothing else is streaming: open this call now. If chunks for
174	                    // it were buffered while another call held the single active
175	                    // span, replay them first — they were received before this one,
176	                    // and a client concatenating `TOOL_CALL_ARGS` deltas would
177	                    // otherwise rebuild the call's arguments out of order.
178	                    let buffered = self.take_buffered(call_id);
179	                    out.push(event::tool_call_start(
180	                        call_id,
181	                        self.name_of(call_id),
182	                        &self.current_message,
183	                    ));
184	                    if let Some(buffered) = buffered {
185	                        out.push(event::tool_call_args(call_id, &buffered));
186	                    }
187	                    out.push(event::tool_call_args(call_id, args_delta));
188	                    self.open_call = Some(call_id.clone());
189	                } else {
