300	                self.close_all(&mut out);
301	                self.streamed_text = false;
302	                out.push(event::run_error("AGENT_ERROR", error));
303	            }
304	            // `AgentEvent` is `#[non_exhaustive]`: a variant added to core later must
305	            // degrade to a lossless CUSTOM event rather than vanish.
306	            other => out.push(self.custom("helikon.unknown", other)),
307	        }
