        "Does nothing."
    }
    fn schema(&self) -> &Value {
        &self.schema
    }

    async fn invoke(&self, _ctx: &ToolContext<()>, _args: Value) -> Result<ToolOutput, ToolError> {
        Ok(ToolOutput::default())
    }
}

