        &self,
        _agent: &(dyn Agent<()> + '_),
        _ctx: RunContext<()>,
        _input: AgentInput,
        _config: RunConfig,
    ) -> Result<RunResult, RunError> {
        Ok(RunResult::default())
    }

    async fn run_streamed(
        &self,
        _agent: &(dyn Agent<()> + '_),
        _ctx: RunContext<()>,
        _input: AgentInput,
        _config: RunConfig,
    ) -> Result<RunResultStreaming, RunError> {
        let stream: BoxStream<'static, AgentEvent> = Box::pin(EmptyAgentEvents);
        Ok(RunResultStreaming::new(stream))
    }
}

